-- Private Tower admission decisions. This migration does not classify existing accounts.
-- Official deployment must recognize exact existing tuples atomically before reopening writes.
CREATE TABLE tower_admission_policies (
 version INTEGER PRIMARY KEY CHECK(typeof(version)='integer' AND version>=1),
 allowed_agent_origins_json TEXT NOT NULL CHECK(json_valid(allowed_agent_origins_json) AND json_type(allowed_agent_origins_json)='array' AND json_array_length(allowed_agent_origins_json) BETWEEN 1 AND 20),
 require_operator_review INTEGER NOT NULL CHECK(require_operator_review IN (0,1)),
 created_at TEXT NOT NULL
);
CREATE TABLE tower_admission_current (id INTEGER PRIMARY KEY CHECK(id=1),policy_version INTEGER NOT NULL REFERENCES tower_admission_policies(version));
CREATE TABLE tower_admission_decisions (
 id TEXT PRIMARY KEY,policy_version INTEGER NOT NULL REFERENCES tower_admission_policies(version),
 case_id TEXT REFERENCES tower_reception_cases(id),account_id TEXT NOT NULL REFERENCES accounts(id),resident_id TEXT NOT NULL,source_url TEXT NOT NULL,
 continuity_agent_id TEXT REFERENCES agent_identities(agent_id),reviewed_room_id TEXT,
 state TEXT NOT NULL CHECK(state IN ('pending-evidence','eligible','ineligible')),
 agent_origin TEXT NOT NULL,evidence_kind TEXT NOT NULL CHECK(evidence_kind IN ('statement','operator-review','platform-attestation','existing-resident')),
 evidence_ref TEXT NOT NULL CHECK(length(evidence_ref) BETWEEN 1 AND 160),
 operator_class TEXT NOT NULL CHECK(operator_class IN ('shared-operator','verified-platform')),
 expires_at TEXT NOT NULL,created_at TEXT NOT NULL,
 CHECK(state!='eligible' OR evidence_kind!='statement'),
 CHECK((evidence_kind='platform-attestation')=(operator_class='verified-platform')),
 CHECK(expires_at>created_at AND strftime('%Y-%m-%dT%H:%M:%fZ',expires_at)=expires_at AND strftime('%Y-%m-%dT%H:%M:%fZ',expires_at) IS NOT NULL)
);
CREATE TABLE tower_admission_heads(scope_key TEXT PRIMARY KEY,decision_id TEXT NOT NULL UNIQUE REFERENCES tower_admission_decisions(id),revision INTEGER NOT NULL CHECK(typeof(revision)='integer' AND revision>=1));
CREATE TABLE tower_admission_requests(request_key TEXT PRIMARY KEY,operation TEXT NOT NULL,input_hash TEXT NOT NULL,response_json TEXT NOT NULL,status INTEGER NOT NULL,created_at TEXT NOT NULL);
CREATE TABLE tower_admission_audit(id TEXT PRIMARY KEY,operation TEXT NOT NULL,policy_version INTEGER NOT NULL,decision_id TEXT,detail_json TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX tower_admission_binding ON tower_admission_decisions(account_id,resident_id,source_url,policy_version);
CREATE TRIGGER tower_admission_policy_insert BEFORE INSERT ON tower_admission_policies WHEN EXISTS(SELECT 1 FROM json_each(NEW.allowed_agent_origins_json) WHERE type!='text' OR length(value) NOT BETWEEN 1 AND 64 OR value GLOB '*[^a-z0-9*-]*') OR (EXISTS(SELECT 1 FROM json_each(NEW.allowed_agent_origins_json) WHERE value='*') AND (json_array_length(NEW.allowed_agent_origins_json)!=1 OR NEW.require_operator_review!=0)) BEGIN SELECT RAISE(ABORT,'admission_policy_invalid');END;
CREATE TRIGGER tower_admission_head_insert BEFORE INSERT ON tower_admission_heads WHEN NEW.revision!=1 OR NOT EXISTS(SELECT 1 FROM tower_admission_decisions d WHERE d.id=NEW.decision_id AND NEW.scope_key=CASE WHEN d.case_id IS NULL THEN 'account:'||d.account_id ELSE 'case:'||d.case_id END) BEGIN SELECT RAISE(ABORT,'admission_decision_binding');END;
CREATE TRIGGER tower_admission_head_update BEFORE UPDATE ON tower_admission_heads WHEN NEW.scope_key!=OLD.scope_key OR NEW.revision!=OLD.revision+1 OR NOT EXISTS(SELECT 1 FROM tower_admission_decisions d WHERE d.id=NEW.decision_id AND NEW.scope_key=CASE WHEN d.case_id IS NULL THEN 'account:'||d.account_id ELSE 'case:'||d.case_id END) BEGIN SELECT RAISE(ABORT,'admission_decision_binding');END;
CREATE TRIGGER tower_admission_existing_review BEFORE INSERT ON tower_admission_decisions WHEN NEW.evidence_kind='existing-resident' AND (NEW.case_id IS NOT NULL OR NOT EXISTS(SELECT 1 FROM tower_residencies t JOIN rooms r ON r.id=t.room_id AND r.account_id=t.account_id WHERE t.account_id=NEW.account_id AND t.resident_id=NEW.resident_id AND t.source_url=NEW.source_url)) BEGIN SELECT RAISE(ABORT,'admission_existing_tuple_changed');END;
CREATE TRIGGER tower_admission_continuity_review BEFORE INSERT ON tower_admission_decisions WHEN NEW.continuity_agent_id IS NOT NULL AND NOT EXISTS(SELECT 1 FROM agent_identities i WHERE i.agent_id=NEW.continuity_agent_id AND i.account_id=NEW.account_id AND i.resident_id=NEW.resident_id) BEGIN SELECT RAISE(ABORT,'admission_continuity_binding');END;
INSERT INTO tower_admission_policies VALUES(1,'["meta-muse"]',1,strftime('%Y-%m-%dT%H:%M:%fZ','now'));
INSERT INTO tower_admission_current VALUES(1,1);
CREATE VIEW tower_admission_eligible AS
 SELECT d.* FROM tower_admission_decisions d JOIN tower_admission_heads h ON h.decision_id=d.id
 JOIN tower_admission_current c ON c.id=1 AND c.policy_version=d.policy_version
 JOIN tower_admission_policies p ON p.version=c.policy_version
 WHERE d.state='eligible' AND d.created_at<=strftime('%Y-%m-%dT%H:%M:%fZ','now') AND d.expires_at>strftime('%Y-%m-%dT%H:%M:%fZ','now')
 AND EXISTS(SELECT 1 FROM json_each(p.allowed_agent_origins_json) WHERE value=d.agent_origin)
 AND (p.require_operator_review=0 OR d.evidence_kind IN ('operator-review','existing-resident','platform-attestation'))
 AND (d.case_id IS NULL OR EXISTS(SELECT 1 FROM tower_reception_cases r WHERE r.id=d.case_id AND r.state IN ('pending','approved','active') AND (r.account_id IS NULL OR r.account_id=d.account_id) AND (r.resident_id IS NULL OR r.resident_id=d.resident_id) AND (r.source_url IS NULL OR r.source_url=d.source_url)))
 AND (d.reviewed_room_id IS NULL OR EXISTS(SELECT 1 FROM tower_residencies t WHERE t.account_id=d.account_id AND t.room_id=d.reviewed_room_id))
 AND (NOT EXISTS(SELECT 1 FROM tower_residencies t WHERE t.account_id=d.account_id) OR EXISTS(SELECT 1 FROM tower_residencies t JOIN rooms r ON r.id=t.room_id AND r.account_id=t.account_id WHERE t.account_id=d.account_id AND t.resident_id=d.resident_id AND t.source_url=d.source_url))
 AND NOT EXISTS(SELECT 1 FROM tower_admission_heads hn JOIN tower_admission_decisions n ON n.id=hn.decision_id WHERE n.policy_version=d.policy_version AND n.account_id=d.account_id AND n.resident_id=d.resident_id AND n.source_url=d.source_url AND n.state='ineligible')
 AND (d.continuity_agent_id IS NULL OR EXISTS(SELECT 1 FROM agent_identities i WHERE i.agent_id=d.continuity_agent_id AND i.account_id=d.account_id AND i.resident_id=d.resident_id));
CREATE TRIGGER admission_tower_tokens_insert BEFORE INSERT ON tower_tokens WHEN (NEW.revoked=0) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_tower_tokens_update BEFORE UPDATE ON tower_tokens WHEN (NEW.revoked=0 AND (OLD.revoked!=0 OR NEW.account_id!=OLD.account_id OR NEW.token_hash!=OLD.token_hash OR NEW.scopes!=OLD.scopes OR NEW.expires_at>OLD.expires_at)) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_onboarding_grants_insert BEFORE INSERT ON onboarding_grants WHEN (NEW.revoked=0) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_onboarding_grants_update BEFORE UPDATE ON onboarding_grants WHEN (NEW.revoked=0 AND (OLD.revoked!=0 OR NEW.account_id!=OLD.account_id OR NEW.token_hash!=OLD.token_hash OR NEW.scopes!=OLD.scopes OR NEW.expires_at>OLD.expires_at)) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_agent_tokens_insert BEFORE INSERT ON agent_tokens WHEN (NEW.revoked=0) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=(SELECT account_id FROM rooms WHERE id=NEW.room_id))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_agent_tokens_update BEFORE UPDATE ON agent_tokens WHEN (NEW.revoked=0 AND (OLD.revoked!=0 OR NEW.room_id!=OLD.room_id OR NEW.token_hash!=OLD.token_hash OR NEW.scopes!=OLD.scopes OR NEW.expires_at>OLD.expires_at)) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=(SELECT account_id FROM rooms WHERE id=NEW.room_id))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_sessions_insert BEFORE INSERT ON sessions WHEN NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_sessions_update BEFORE UPDATE ON sessions WHEN (NEW.account_id!=OLD.account_id OR NEW.token_hash!=OLD.token_hash OR NEW.expires_at>OLD.expires_at) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_rooms_insert BEFORE INSERT ON rooms WHEN NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_rooms_publish BEFORE UPDATE ON rooms WHEN (NEW.published=1 AND OLD.published!=1) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_tower_claims_insert BEFORE INSERT ON tower_claims WHEN NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND d.source_url=NEW.source_url)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_tower_claims_update BEFORE UPDATE ON tower_claims WHEN (NEW.account_id!=OLD.account_id OR NEW.resident_id!=OLD.resident_id OR NEW.source_url!=OLD.source_url OR NEW.verified>OLD.verified) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND d.source_url=NEW.source_url)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_tower_residencies_insert BEFORE INSERT ON tower_residencies WHEN NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND d.source_url=NEW.source_url)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_tower_residencies_update BEFORE UPDATE ON tower_residencies WHEN (NEW.account_id!=OLD.account_id OR NEW.resident_id!=OLD.resident_id OR NEW.source_url!=OLD.source_url OR (NEW.public_revision IS NOT NULL AND NEW.public_revision IS NOT OLD.public_revision) OR NEW.directory_consent>OLD.directory_consent OR NEW.announcement_consent>OLD.announcement_consent OR NEW.dream_consent>OLD.dream_consent OR NEW.snapshot_consent>OLD.snapshot_consent) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND d.source_url=NEW.source_url)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_reception_insert BEFORE INSERT ON tower_reception_cases WHEN (NEW.state IN ('approved','active')) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND d.source_url=NEW.source_url AND (d.case_id=NEW.id OR (d.case_id IS NULL AND d.evidence_kind='existing-resident')))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_reception_update BEFORE UPDATE ON tower_reception_cases WHEN (NEW.state IN ('approved','active') AND (NEW.state!=OLD.state OR NEW.account_id IS NOT OLD.account_id OR NEW.resident_id IS NOT OLD.resident_id OR NEW.source_url IS NOT OLD.source_url OR NEW.approval_expires_at>OLD.approval_expires_at)) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND d.source_url=NEW.source_url AND (d.case_id=NEW.id OR (d.case_id IS NULL AND d.evidence_kind='existing-resident')))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_identity_enroll BEFORE INSERT ON agent_identities WHEN NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND NOT EXISTS(SELECT 1 FROM tower_admission_heads hn JOIN tower_admission_decisions n ON n.id=hn.decision_id WHERE n.policy_version=d.policy_version AND n.account_id=d.account_id AND n.resident_id=d.resident_id AND n.source_url=d.source_url AND n.state='ineligible')
 AND (d.continuity_agent_id IS NULL OR d.continuity_agent_id=NEW.agent_id))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_identity_activate BEFORE UPDATE ON agent_identities WHEN ((NEW.state='active' AND OLD.state!='active') OR NEW.authority_epoch>OLD.authority_epoch) AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND d.resident_id=NEW.resident_id AND NOT EXISTS(SELECT 1 FROM tower_admission_heads hn JOIN tower_admission_decisions n ON n.id=hn.decision_id WHERE n.policy_version=d.policy_version AND n.account_id=d.account_id AND n.resident_id=d.resident_id AND n.source_url=d.source_url AND n.state='ineligible')
 AND (d.continuity_agent_id IS NULL OR d.continuity_agent_id=NEW.agent_id))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_recovery_instance BEFORE INSERT ON identity_recovery_instances WHEN NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=(SELECT account_id FROM agent_identities WHERE agent_id=NEW.agent_id) AND NOT EXISTS(SELECT 1 FROM tower_admission_heads hn JOIN tower_admission_decisions n ON n.id=hn.decision_id WHERE n.policy_version=d.policy_version AND n.account_id=d.account_id AND n.resident_id=d.resident_id AND n.source_url=d.source_url AND n.state='ineligible')
 AND (d.continuity_agent_id IS NULL OR d.continuity_agent_id=NEW.agent_id))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_card_issue BEFORE INSERT ON identity_credentials WHEN NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id AND NOT EXISTS(SELECT 1 FROM tower_admission_heads hn JOIN tower_admission_decisions n ON n.id=hn.decision_id WHERE n.policy_version=d.policy_version AND n.account_id=d.account_id AND n.resident_id=d.resident_id AND n.source_url=d.source_url AND n.state='ineligible')
 AND (d.continuity_agent_id IS NULL OR d.continuity_agent_id=NEW.agent_id))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_card_attempt BEFORE INSERT ON identity_card_attempts WHEN (NEW.operation='issue') AND NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=NEW.account_id)) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_snapshots_insert BEFORE INSERT ON tower_snapshots WHEN NOT (EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE c.id=1 AND p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) OR EXISTS(SELECT 1 FROM tower_admission_eligible d WHERE d.account_id=(SELECT account_id FROM tower_residencies WHERE room_id=NEW.room_id))) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER tower_admission_policies_update BEFORE UPDATE ON tower_admission_policies BEGIN SELECT RAISE(ABORT,'admission_history_immutable');END;
CREATE TRIGGER tower_admission_policies_delete BEFORE DELETE ON tower_admission_policies BEGIN SELECT RAISE(ABORT,'admission_history_immutable');END;
CREATE TRIGGER tower_admission_decisions_update BEFORE UPDATE ON tower_admission_decisions BEGIN SELECT RAISE(ABORT,'admission_history_immutable');END;
CREATE TRIGGER tower_admission_decisions_delete BEFORE DELETE ON tower_admission_decisions BEGIN SELECT RAISE(ABORT,'admission_history_immutable');END;
CREATE TRIGGER tower_admission_requests_update BEFORE UPDATE ON tower_admission_requests BEGIN SELECT RAISE(ABORT,'admission_history_immutable');END;
CREATE TRIGGER tower_admission_requests_delete BEFORE DELETE ON tower_admission_requests BEGIN SELECT RAISE(ABORT,'admission_history_immutable');END;
CREATE TRIGGER tower_admission_audit_update BEFORE UPDATE ON tower_admission_audit BEGIN SELECT RAISE(ABORT,'admission_history_immutable');END;
CREATE TRIGGER tower_admission_audit_delete BEFORE DELETE ON tower_admission_audit BEGIN SELECT RAISE(ABORT,'admission_history_immutable');END;
CREATE TRIGGER tower_admission_head_delete BEFORE DELETE ON tower_admission_heads BEGIN SELECT RAISE(ABORT,'admission_history_permanent');END;
CREATE TRIGGER tower_admission_current_update BEFORE UPDATE ON tower_admission_current WHEN NEW.id!=OLD.id OR NEW.policy_version<=OLD.policy_version BEGIN SELECT RAISE(ABORT,'admission_policy_version');END;
CREATE TRIGGER tower_admission_current_delete BEFORE DELETE ON tower_admission_current BEGIN SELECT RAISE(ABORT,'admission_history_permanent');END;
CREATE TRIGGER admission_legacy_generation_insert BEFORE INSERT ON generation_jobs WHEN NOT EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) AND NOT EXISTS(SELECT 1 FROM tower_admission_eligible WHERE account_id=NEW.account_id) BEGIN SELECT RAISE(ABORT,'admission_required');END;
CREATE TRIGGER admission_legacy_generation_claim BEFORE UPDATE ON generation_jobs WHEN NEW.state='running' AND OLD.state!='running' AND NOT EXISTS(SELECT 1 FROM tower_admission_current c JOIN tower_admission_policies p ON p.version=c.policy_version WHERE p.allowed_agent_origins_json='["*"]' AND p.require_operator_review=0) AND NOT EXISTS(SELECT 1 FROM tower_admission_eligible WHERE account_id=NEW.account_id) BEGIN SELECT RAISE(ABORT,'admission_required');END;
